using JustRecorder.Core;
namespace JustRecorder.Windows;

internal sealed class SettingsForm : Form
{
    readonly Settings draft; readonly Action<Settings, bool, string, bool> save; readonly HotKey hotkey;
    readonly TabControl tabs = new() { Dock = DockStyle.Fill }; readonly Label feedback = new() { AutoSize = true, ForeColor = SystemColors.ControlText, MaximumSize = new Size(580, 0) };
    readonly TextBox folder = new() { ReadOnly = true }, template = new(), preview = new() { ReadOnly = true, Multiline = true, Height = 60, ScrollBars = ScrollBars.Vertical }, endpoint = new(), model = new(), key = new() { UseSystemPasswordChar = true }, prompt = new() { Multiline = true, ScrollBars = ScrollBars.Vertical, Height = 110 };
    readonly ComboBox format = new() { DropDownStyle = ComboBoxStyle.DropDownList }, bitrate = new() { DropDownStyle = ComboBoxStyle.DropDownList }, mp3Bitrate = new() { DropDownStyle = ComboBoxStyle.DropDownList }, rate = new() { DropDownStyle = ComboBoxStyle.DropDownList };
    readonly NumericUpDown stop = new() { Minimum = 0, Maximum = 30 }, preSeconds = new() { Minimum = 5, Maximum = 30 }, timeout = new() { Minimum = 2, Maximum = 120 };
    readonly CheckBox pre = new() { Text = "Include recent audio" }, metadata = new() { Text = "Use Windows player track metadata" }, ai = new() { Text = "Use AI naming" }, sounds = new() { Text = "Play a sound after stopping" }, timer = new() { Text = "Show duration in tray tooltip" }, reveal = new() { Text = "Reveal after saving" }, login = new() { Text = "Launch at login" };
    readonly Button shortcut = new() { AutoSize = true }; readonly Label detectResult = new() { AutoSize = true, MaximumSize = new Size(560, 0) }, aiResult = new() { AutoSize = true, MaximumSize = new Size(560, 0) };
    readonly CancellationTokenSource lifetime = new(); bool keyDirty, listening, savedOnClose;
    public SettingsForm(Settings settings, Action<Settings, bool, string, bool> save, HotKey hotkey)
    {
        draft = settings with { }; this.save = save; this.hotkey = hotkey;
        Text = "JustRecorder Settings"; ClientSize = new Size(660, 690); MinimumSize = new Size(580, 500); StartPosition = FormStartPosition.CenterScreen; AutoScaleMode = AutoScaleMode.Dpi; KeyPreview = true;
        var footer = new FlowLayoutPanel { Dock = DockStyle.Bottom, AutoSize = true, Padding = new Padding(12), FlowDirection = FlowDirection.RightToLeft };
        var apply = new Button { Text = "Save", AutoSize = true }; apply.Click += (_, _) => TrySave(); var done = new Button { Text = "Done", AutoSize = true }; done.Click += (_, _) => { if (TrySave()) { savedOnClose = true; Close(); } };
        var discard = new Button { Text = "Discard unsaved edits", AutoSize = true };
        discard.Click += (_, _) => { savedOnClose = true; Close(); };
        footer.Controls.Add(done); footer.Controls.Add(apply); footer.Controls.Add(discard); footer.Controls.Add(feedback); Controls.Add(tabs); Controls.Add(footer);
        foreach (var toggle in new[] { pre, metadata, ai, sounds, timer, reveal, login }) toggle.AutoSize = true;
        var capture = Page("Capture"); folder.Text = draft.SaveFolder; Row(capture, "Save folder", folder); var browse = Button("Choose folder…", () => { using var dialog = new FolderBrowserDialog { InitialDirectory = folder.Text }; if (dialog.ShowDialog(this) == DialogResult.OK) folder.Text = dialog.SelectedPath; }); capture.Controls.Add(browse);
        shortcut.Text = TrayApp.Shortcut(draft); shortcut.Click += (_, _) => { listening = !listening; hotkey.Enabled = !listening; shortcut.Text = listening ? "Press shortcut — Escape cancels" : TrayApp.Shortcut(draft); }; Row(capture, "Global shortcut", shortcut);
        stop.Value = draft.AutoStopMinutes; Row(capture, "Auto-stop (minutes; 0 = never)", stop);
        format.Items.AddRange(Enum.GetValues<AudioKind>().Cast<object>().ToArray()); format.SelectedItem = draft.Format; Row(capture, "Format", format);
        bitrate.Items.AddRange([128, 160, 192, 256, 320]); bitrate.SelectedItem = draft.Bitrate; Row(capture, "AAC bitrate (kbps)", bitrate);
        mp3Bitrate.Items.AddRange([128, 160, 192, 256, 320]); mp3Bitrate.SelectedItem = draft.Mp3Bitrate; Row(capture, "MP3 bitrate (kbps)", mp3Bitrate);
        rate.Items.AddRange([44100, 48000]); rate.SelectedItem = draft.SampleRate; Row(capture, "Sample rate (Hz)", rate);
        var formatNote = Note(capture, ""); var sizeNote = Note(capture, "");
        void SizeNote() { var k = (AudioKind)format.SelectedItem!; var sr = (int)(rate.SelectedItem ?? 48000); var kb = (int)(k == AudioKind.Mp3 ? mp3Bitrate.SelectedItem ?? 320 : bitrate.SelectedItem ?? 256); var mb = k is AudioKind.Aac or AudioKind.Mp3 ? kb * 60.0 / 8 / 1024 : sr * 2.0 * (k == AudioKind.Wav16 ? 2 : 3) * 60 / 1048576 * (k == AudioKind.Alac ? 0.6 : 1); sizeNote.Text = $"About {mb:F1} MB per minute. Recording temporarily uses {sr * 8.0 * 60 / 1048576:F0} MB per minute for the original WAV."; }
        bitrate.SelectedIndexChanged += (_, _) => SizeNote(); mp3Bitrate.SelectedIndexChanged += (_, _) => SizeNote(); rate.SelectedIndexChanged += (_, _) => SizeNote();
        void FormatNote() { var k = (AudioKind)format.SelectedItem!; bitrate.Enabled = k == AudioKind.Aac; mp3Bitrate.Enabled = k == AudioKind.Mp3; SizeNote(); formatNote.Text = k == AudioKind.Alac ? (Encoder.Ffmpeg == null ? "Apple Lossless needs ffmpeg.exe beside JustRecorder or on PATH. If unavailable, your original WAV is kept." : "Apple Lossless uses the installed FFmpeg encoder.") : k is AudioKind.Aac or AudioKind.Mp3 ? "Windows encodes this format. If the codec is unavailable, the original WAV is kept." : "Uncompressed stereo WAV for editing."; UpdatePreview(); }
        format.SelectedIndexChanged += (_, _) => FormatNote();
        pre.Checked = draft.PreRoll; capture.Controls.Add(pre); preSeconds.Value = draft.PreRollSeconds; Row(capture, "Pre-roll (seconds)", preSeconds); Note(capture, "Pre-roll keeps the capture stream active in memory. Recording follows the default Windows playback device; audio is never rerouted.");
        var naming = Page("Naming"); template.Text = draft.Template; Row(naming, "File name template", template); Row(naming, "Preview", preview); template.TextChanged += (_, _) => UpdatePreview(); naming.Controls.Add(Button("Restore default template", () => template.Text = Settings.DefaultTemplate));
        Note(naming, "Tokens: {title}, {raw_title}, {artist}, {track}, {app}, {duration}, {seconds}, {format}, {date}, {time}, {datetime}.\nOptional groups such as [{artist} - ] disappear when a token is empty."); metadata.Checked = draft.PlayerMetadata; naming.Controls.Add(metadata);
        var detect = Button("Test detection", () => { }); detect.Click += async (_, _) => { detect.Enabled = false; detectResult.Text = "Checking…"; try { using var deadline = CancellationTokenSource.CreateLinkedTokenSource(lifetime.Token); deadline.CancelAfter(TimeSpan.FromSeconds(3)); var source = await SourceDetector.Detect(metadata.Checked, deadline.Token); detectResult.Text = $"App: {source.App}\nTitle: {source.Title}\nArtist: {source.Artist}\nWindow: {source.Raw}"; } catch (Exception ex) { if (!IsDisposed) detectResult.Text = ex.Message; } finally { if (!IsDisposed) detect.Enabled = true; } }; naming.Controls.Add(detect); naming.Controls.Add(detectResult);
        var aiPage = Page("AI naming"); ai.Checked = draft.AiEnabled; aiPage.Controls.Add(ai); Note(aiPage, "Only title, artist, app name and duration are sent to your endpoint. Audio stays on this PC. Failed requests fall back to local naming."); endpoint.Text = draft.BaseUrl; Row(aiPage, "Base URL", endpoint); model.Text = draft.Model; Row(aiPage, "Model", model);
        try { key.Text = Platform.KeyRead(); } catch (Exception ex) { feedback.Text = "Credential Manager could not be read: " + ex.Message; }
        key.TextChanged += (_, _) => keyDirty = true; Row(aiPage, "API key (Windows Credential Manager)", key); prompt.Text = draft.Prompt; Row(aiPage, "Instructions", prompt); timeout.Value = draft.AiTimeout; Row(aiPage, "Timeout (seconds)", timeout);
        aiPage.Controls.Add(Button("Restore default instructions", () => prompt.Text = new Settings().Prompt));
        var test = Button("Send a sample title", () => { }); test.Click += async (_, _) => { test.Enabled = false; aiResult.Text = "Sending…"; try { var config = Read(); var title = await AiNamer.Suggest(config, key.Text, new Source("Browser", "Example Artist - Example Track (Live) - YouTube", "Example Artist", "Example Track (Live)"), 63, lifetime.Token); if (!IsDisposed) aiResult.Text = title; } catch (Exception ex) { if (!IsDisposed) aiResult.Text = ex.Message; } finally { if (!IsDisposed) test.Enabled = true; } }; aiPage.Controls.Add(test); aiPage.Controls.Add(aiResult);
        var general = Page("General"); login.Checked = Platform.LaunchAtLogin; general.Controls.Add(login); sounds.Checked = draft.Sounds; timer.Checked = draft.Timer; reveal.Checked = draft.Reveal; general.Controls.Add(sounds); general.Controls.Add(timer); general.Controls.Add(reveal);
        Note(general, "Windows 10 version 2004 (build 19041) or newer. Uses the default playback device with WASAPI loopback; no virtual audio driver or microphone permission is needed. Exclusive-mode or protected playback may not be capturable.\n\nWith pre-roll enabled, stop sounds are suppressed so they do not enter the next clip. Windows N editions may need the Media Feature Pack for AAC/MP3; WAV remains available."); general.Controls.Add(Button("Open Windows sound settings", () => System.Diagnostics.Process.Start(new System.Diagnostics.ProcessStartInfo("ms-settings:sound") { UseShellExecute = true })));
        tabs.SelectedIndexChanged += (_, _) => CancelShortcut(); Deactivate += (_, _) => CancelShortcut(); FormClosing += (_, e) => { CancelShortcut(); if (!savedOnClose && !TrySave()) { e.Cancel = true; return; } lifetime.Cancel(); }; FormClosed += (_, _) => lifetime.Dispose();
        KeyDown += (_, e) => { if (!listening) return; e.SuppressKeyPress = true; e.Handled = true; if (e.KeyCode == Keys.Escape) { CancelShortcut(); return; } var modifiers = (e.Alt ? 1u : 0) | (e.Control ? 2u : 0) | (e.Shift ? 4u : 0); if (modifiers == 0 || e.KeyCode is Keys.ControlKey or Keys.ShiftKey or Keys.Menu) return; draft.HotKey = (uint)e.KeyCode; draft.Modifiers = modifiers; CancelShortcut(); };
        FormatNote(); UpdatePreview();
    }
    public void CloseAfterSave() { savedOnClose = true; Close(); }

    void CancelShortcut() { listening = false; hotkey.Enabled = true; shortcut.Text = TrayApp.Shortcut(draft); }
    Settings Read() { var s = draft with { SaveFolder = folder.Text.Trim(), Format = (AudioKind)format.SelectedItem!, SampleRate = (int)rate.SelectedItem!, AutoStopMinutes = (int)stop.Value, PreRoll = pre.Checked, PreRollSeconds = (int)preSeconds.Value, Template = template.Text, PlayerMetadata = metadata.Checked, AiEnabled = ai.Checked, BaseUrl = endpoint.Text.Trim(), Model = model.Text.Trim(), Prompt = prompt.Text, AiTimeout = (int)timeout.Value, Sounds = sounds.Checked, Timer = timer.Checked, Reveal = reveal.Checked }; s.Mp3Bitrate = (int)mp3Bitrate.SelectedItem!; s.Bitrate = (int)bitrate.SelectedItem!; return s; }
    public bool TrySave() { try { var s = Read(); if (!Path.IsPathFullyQualified(s.SaveFolder)) throw new ArgumentException("Choose an absolute save-folder path."); Directory.CreateDirectory(s.SaveFolder); var probe = Path.Combine(s.SaveFolder, $".riff-check-{Guid.NewGuid():N}"); using (File.Create(probe)) { } File.Delete(probe); if (s.AiEnabled) { AiNamer.Endpoint(s.BaseUrl); if (s.Model.Length == 0) throw new ArgumentException("Enter an AI model name."); } save(s, login.Checked, key.Text.Trim(), keyDirty); keyDirty = false; feedback.ForeColor = SystemColors.GrayText; feedback.Text = "Saved."; return true; } catch (Exception ex) { feedback.ForeColor = SystemColors.ControlText; feedback.Text = ex.Message; return false; } }
    void UpdatePreview() { if (format.SelectedItem is AudioKind kind) preview.Text = Naming.Render(template.Text, new Source("Browser", "Example Artist - Example Track", "Example Artist", "Example Track"), 63, kind, DateTime.Now) + "." + Naming.Extension(kind); }
    FlowLayoutPanel Page(string title) { var page = new TabPage(title); var panel = new FlowLayoutPanel { Dock = DockStyle.Fill, AutoScroll = true, FlowDirection = FlowDirection.TopDown, WrapContents = false, Padding = new Padding(18) }; page.Controls.Add(panel); tabs.TabPages.Add(page); panel.SizeChanged += (_, _) => { foreach (Control c in panel.Controls) if (c is Panel or Label) c.Width = Math.Max(350, panel.ClientSize.Width - 48); }; return panel; }
    static void Row(FlowLayoutPanel page, string label, Control control) { var box = new Panel { Width = 580, Height = control is TextBox { Multiline: true } ? 140 : 64 }; var text = new Label { Text = label, AutoSize = true, Dock = DockStyle.Top }; control.AccessibleName = label; control.Dock = DockStyle.Bottom; control.Width = 580; box.Controls.Add(control); box.Controls.Add(text); page.Controls.Add(box); }
    static Label Note(FlowLayoutPanel page, string text) { var label = new Label { Text = text, AutoSize = true, MaximumSize = new Size(580, 0), Margin = new Padding(0, 8, 0, 14) }; page.Controls.Add(label); return label; }
    static Button Button(string title, Action action) { var button = new Button { Text = title, AutoSize = true, MinimumSize = new Size(0, 30) }; button.Click += (_, _) => action(); return button; }
}
